import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, Switch, Button } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

const SettingsScreen = ({ navigation }) => {
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);

  useEffect(() => {
    // Load settings from AsyncStorage when the component mounts
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      const darkMode = await AsyncStorage.getItem('darkMode');
      const notifications = await AsyncStorage.getItem('notifications');

      if (darkMode !== null) {
        setIsDarkMode(darkMode === 'true');
      }
      if (notifications !== null) {
        setNotificationsEnabled(notifications === 'true');
      }
    } catch (error) {
      console.error('Error loading settings:', error);
    }
  };

  const toggleDarkMode = async () => {
    setIsDarkMode(!isDarkMode);
    await AsyncStorage.setItem('darkMode', !isDarkMode.toString());
  };

  const toggleNotifications = async () => {
    setNotificationsEnabled(!notificationsEnabled);
    await AsyncStorage.setItem('notifications', !notificationsEnabled.toString());
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Settings</Text>

      <View style={styles.settingItem}>
        <Text style={styles.settingLabel}>Dark Mode</Text>
        <Switch
          value={isDarkMode}
          onValueChange={toggleDarkMode}
        />
      </View>

      <View style={styles.settingItem}>
        <Text style={styles.settingLabel}>Notifications</Text>
        <Switch
          value={notificationsEnabled}
          onValueChange={toggleNotifications}
        />
      </View>

      <Button
        title="Clear All Settings"
        onPress={async () => {
          try {
            await AsyncStorage.removeItem('darkMode');
            await AsyncStorage.removeItem('notifications');
            setIsDarkMode(false);
            setNotificationsEnabled(true);
          } catch (error) {
            console.error('Error clearing settings:', error);
          }
        }}
      />

      <Button
        title="Go Back"
        onPress={() => navigation.goBack()}
      />
    </View>
  );
};

