import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;

@Service
public class QueryScheduler {

    @Value("${sql.query.file}")
    private String sqlQueryFile;

    @Value("${output.file}")
    private String outputFile;

    @Value("${scheduling.interval}")
    private long schedulingInterval; // in milliseconds

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Scheduled(fixedRate = "${scheduling.interval}")
    public void executeQueryAndStore() {
        try {
            String sqlQuery = readSqlQueryFromFile(sqlQueryFile);
            List<String> results = jdbcTemplate.queryForList(sqlQuery, String.class); // Adjust return type as needed
            storeResultsToFile(results, outputFile);
        } catch (Exception e) {
            System.err.println("Error executing query and storing results: " + e.getMessage());
            e.printStackTrace(); // Log the full stack trace for debugging
        }
    }

    private String readSqlQueryFromFile(String filePath) throws IOException {
        return new String(Files.readAllBytes(Paths.get(filePath)));
    }

    private void storeResultsToFile(List<String> results, String filePath) throws IOException {
        try (FileWriter writer = new FileWriter(filePath, true)) { // Append to file
            for (String result : results) {
                writer.write(result + "\n");
            }
        }
    }
}
